import pyomo.environ as pyo

DATA = {
    "projects": ["X", "Y"],
    "cost": {"X": 40, "Y": 50},
    "resource_coef": {"X": 5, "Y": 3},
    "min_total_investment": 30,
    "resource_limit": 150,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.PROJECTS = pyo.Set(initialize=d["projects"])

    # Investment units per project (integer, nonnegative)
    model.invest = pyo.Var(
        model.PROJECTS,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][p] * m.invest[p] for p in m.PROJECTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Total investment must be at least the minimum operational requirement
    def min_total_rule(m):
        return sum(m.invest[p] for p in m.PROJECTS) >= d["min_total_investment"]

    model.min_total_investment = pyo.Constraint(rule=min_total_rule)

    # Combined resource usage must not exceed the sustainability limit
    def resource_rule(m):
        return sum(
            d["resource_coef"][p] * m.invest[p] for p in m.PROJECTS
        ) <= d["resource_limit"]

    model.resource_limit = pyo.Constraint(rule=resource_rule)

    return model


